CREATE TABLE IF NOT EXISTS personnel(id INTEGER PRIMARY KEY AUTOINCREMENT,full_name VARCHAR(160) NOT NULL,employee_number VARCHAR(80) NOT NULL UNIQUE,office_id INTEGER NOT NULL,position VARCHAR(160) NOT NULL,classification VARCHAR(20) NOT NULL DEFAULT 'Utility',driver_id INTEGER UNIQUE,license_number VARCHAR(80),license_expiry DATE,contact VARCHAR(80),status VARCHAR(40) NOT NULL,FOREIGN KEY (office_id) REFERENCES offices(id));
CREATE TABLE IF NOT EXISTS personnel_bookings(id INTEGER PRIMARY KEY AUTOINCREMENT,reference VARCHAR(40) NOT NULL UNIQUE,requester_id INTEGER NOT NULL,office_id INTEGER NOT NULL,personnel_id INTEGER,preferred_personnel VARCHAR(160) NOT NULL DEFAULT '',requested_role VARCHAR(160) NOT NULL,destination TEXT NOT NULL,purpose TEXT NOT NULL,start_datetime DATETIME NOT NULL,end_datetime DATETIME NOT NULL,status VARCHAR(50) NOT NULL,created_at DATETIME NOT NULL,actual_start DATETIME,actual_end DATETIME,FOREIGN KEY (requester_id) REFERENCES users(id),FOREIGN KEY (office_id) REFERENCES offices(id),FOREIGN KEY (personnel_id) REFERENCES personnel(id));
CREATE TABLE IF NOT EXISTS personnel_booking_history(id INTEGER PRIMARY KEY AUTOINCREMENT,booking_id INTEGER NOT NULL,user_id INTEGER NOT NULL,decision VARCHAR(50) NOT NULL,remarks TEXT,created_at DATETIME NOT NULL,FOREIGN KEY (booking_id) REFERENCES personnel_bookings(id),FOREIGN KEY (user_id) REFERENCES users(id));
CREATE INDEX IF NOT EXISTS idx_personnel_schedule ON personnel_bookings(personnel_id,status,start_datetime,end_datetime);
CREATE TABLE IF NOT EXISTS personnel_booking_assignments(booking_id INTEGER NOT NULL,personnel_id INTEGER NOT NULL,PRIMARY KEY (booking_id,personnel_id),FOREIGN KEY (booking_id) REFERENCES personnel_bookings(id),FOREIGN KEY (personnel_id) REFERENCES personnel(id));
